public static String findTheShortestWord(String input) {
    String[] words = input.split("\s+"); String shortest = ""; for (String word : words) if (shortest.isEmpty() || word.length() < shortest.length()) shortest = word; return shortest;
 }

public static String findTheShortestWord(String input) {
    return Arrays.stream(input.split("\s+")).reduce((shortest, current) -> current.length() < shortest.length() ? current : shortest).orElse("");
 }
